            }

            return $query
                ->filterByEmailProviderConfig($this)
                ->count($con);
        }

        return count($this->collEmailAccounts);
    }

    /**
     * Method called to associate a EmailAccount object to this object
     * through the EmailAccount foreign key attribute.
     *
     * @param    EmailAccount $l EmailAccount
     * @return EmailProviderConfig The current object (for fluent API support)
     */
    public function addEmailAccount(EmailAccount $l)
    {
        if ($this->collEmailAccounts === null) {
            $this->initEmailAccounts();
            $this->collEmailAccountsPartial = true;
        }

        if (!in_array($l, $this->collEmailAccounts->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddEmailAccount($l);

            if ($this->emailAccountsScheduledForDeletion and $this->emailAccountsScheduledForDeletion->contains($l)) {
                $this->emailAccountsScheduledForDeletion->remove($this->emailAccountsScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

    /**
     * @param	EmailAccount $emailAccount The emailAccount object to add.
     */
    protected function doAddEmailAccount($emailAccount)
    {
        $this->collEmailAccounts[]= $emailAccount;
        $emailAccount->setEmailProviderConfig($this);
    }

    /**
     * @param	EmailAccount $emailAccount The emailAccount object to remove.
     * @return EmailProviderConfig The current object (for fluent API support)
     */
    public function removeEmailAccount($emailAccount)
    {
        if ($this->getEmailAccounts()->contains($emailAccount)) {
            $this->collEmailAccounts->remove($this->collEmailAccounts->search($emailAccount));
            if (null === $this->emailAccountsScheduledForDeletion) {
                $this->emailAccountsScheduledForDeletion = clone $this->collEmailAccounts;
                $this->emailAccountsScheduledForDeletion->clear();
            }
            $this->emailAccountsScheduledForDeletion[]= clone $emailAccount;
            $emailAccount->setEmailProviderConfig(null);
        }

        return $this;
    }


    /**
     * If this collection has already been initialized with
     * an identical criteria, it returns the collection.
     * Otherwise if this EmailProviderConfig is new, it will return
     * an empty collection; or if this EmailProviderConfig has previously
     * been saved, it will retrieve related EmailAccounts from storage.
     *
     * This method is protected by default in order to keep the public
     * api reasonable.  You can provide public methods for those you
     * actually need in EmailProviderConfig.
     *
     * @param Criteria $criteria optional Criteria object to narrow the query
     * @param PropelPDO $con optional connection object
     * @param string $join_behavior optional join type to use (defaults to Criteria::LEFT_JOIN)
     * @return PropelObjectCollection|EmailAccount[] List of EmailAccount objects
     */
    public function getEmailAccountsJoinUsuario($criteria = null, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $query = EmailAccountQuery::create(null, $criteria);
        $query->joinWith('Usuario', $join_behavior);

        return $this->getEmailAccounts($query, $con);
    }

    /**
     * Clears the current object and sets all attributes to their default values
     */
    public function clear()
    {
        $this->emailproviderconfig_id = null;
        $this->emailprovider_id = null;
        $this->server_name = null;
        $this->listen_puerto = null;
        $this->type_encryption = null;
        $this->tenant_name = null;
        $this->oauth2_client = null;
        $this->oauth2_secret = null;
        $this->oauth2_redirect_uri = null;
        $this->fecha_creacion = null;
        $this->fecha_modificacion = null;
        $this->alreadyInSave = false;
        $this->alreadyInValidation = false;
        $this->alreadyInClearAllReferencesDeep = false;
        $this->clearAllReferences();
        $this->resetModified();
        $this->setNew(true);
        $this->setDeleted(false);
    }

    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collEmailAccounts) {
                foreach ($this->collEmailAccounts as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aEmailProvider instanceof Persistent) {
              $this->aEmailProvider->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collEmailAccounts instanceof PropelCollection) {
            $this->collEmailAccounts->clearIterator();
        }
        $this->collEmailAccounts = null;
        $this->aEmailProvider = null;
    }

    /**
     * return the string representation of this object
     *
     * @return string
     */
    public function __toString()
    {
        return (string) $this->exportTo(EmailProviderConfigPeer::DEFAULT_STRING_FORMAT);
    }

    /**
     * return true is the object is in saving state
     *
     * @return boolean
     */
    public function isAlreadyInSave()
    {
        return $this->alreadyInSave;
    }

    /**
     * Catches calls to virtual methods
     */
    public function __call($name, $params)
    {
        
        // symfony_behaviors behavior
        if ($callable = sfMixer::getCallable('BaseEmailProviderConfig:' . $name))
        {
          array_unshift($params, $this);
          return call_user_func_array($callable, $params);
        }


        return parent::__call($name, $params);
    }

}
